// GET — read data, no body, safe + idempotent
const users = await fetch('/api/users').then(r => r.json());
const user  = await fetch('/api/users/42').then(r => r.json());

// POST — create, has a body, NOT idempotent
const newUser = await fetch('/api/users', {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify({ name: 'Alice', email: 'alice@example.com' }),
}).then(r => r.json());
// → 201 Created  { id: 100, name: 'Alice', ... }

// PUT — full replace, idempotent (must send complete object)
await fetch('/api/users/42', {
    method:  'PUT',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify({ id: 42, name: 'Alice', email: 'alice@new.com', role: 'admin' }),
});
// → 200 OK  (complete object required — missing fields become null)

// PATCH — partial update, send only changed fields
await fetch('/api/users/42', {
    method:  'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify({ email: 'alice@new.com' }),
});
// → 200 OK  (only email changes; other fields untouched)

// DELETE — remove, idempotent
await fetch('/api/users/42', { method: 'DELETE' });
// → 204 No Content  (no body)

// HEAD — check existence without downloading body
const res = await fetch('/api/files/report.pdf', { method: 'HEAD' });
console.log(res.status);               // 200 or 404
console.log(res.headers.get('content-length')); // file size in bytes
